import React, { useState, useEffect } from "react";

function App() {
  const [darkMode, setDarkMode] = useState(false);
  const [ingredients, setIngredients] = useState("");
  const [mealType, setMealType] = useState("Breakfast");
  const [cuisine, setCuisine] = useState("");
  const [cookingTime, setCookingTime] = useState("Less than 30 minutes");
  const [complexity, setComplexity] = useState("Beginner");
  const [recipes, setRecipes] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    document.documentElement.classList.toggle("dark", darkMode);
  }, [darkMode]);

  const handleSubmit = async () => {
    try {
      const response = await fetch("http://localhost:5000/api/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ingredients,
          mealType,
          cuisine,
          cookingTime,
          complexity,
        }),
      });

      const data = await response.json();
      console.log("API Response:", data);

      if (data.recipe) {
        const normalizedRecipes = Array.isArray(data.recipe)
          ? data.recipe
          : [data.recipe];
        setRecipes(normalizedRecipes);
      } else {
        setRecipes([]);
      }
    } catch (err) {
      console.error("Error generating recipe:", err);
      setError("Failed to generate recipe.");
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-white to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center p-4 transition-colors duration-300">
      <div className="absolute top-4 right-4">
        <button
          onClick={() => setDarkMode(!darkMode)}
          className="bg-gray-800 dark:bg-white text-white dark:text-black px-4 py-2 rounded shadow hover:opacity-80"
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-6xl">
        {/* LEFT - Form */}
        <div className="bg-white dark:bg-gray-700 dark:text-white rounded-xl shadow-md p-6">
          <h2 className="text-xl font-bold text-center mb-6">
            Recipe Generator
          </h2>

          <div className="mb-4">
            <label className="block font-semibold mb-1" htmlFor="ingredients">
              Ingredients
            </label>
            <input
              id="ingredients"
              type="text"
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              placeholder="e.g. tomato, potato, onion"
              value={ingredients}
              onChange={(e) => setIngredients(e.target.value)}
            />
          </div>

          <div className="mb-4">
            <label className="block font-semibold mb-1">Meal Type</label>
            <select
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              value={mealType}
              onChange={(e) => setMealType(e.target.value)}
            >
              <option>Breakfast</option>
              <option>Lunch</option>
              <option>Dinner</option>
              <option>Snack</option>
            </select>
          </div>

          <div className="mb-4">
            <label className="block font-semibold mb-1">
              Cuisine Preference
            </label>
            <input
              type="text"
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              placeholder="e.g. Indian, Italian"
              value={cuisine}
              onChange={(e) => setCuisine(e.target.value)}
            />
          </div>

          <div className="mb-4">
            <label className="block font-semibold mb-1">Cooking Time</label>
            <select
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              value={cookingTime}
              onChange={(e) => setCookingTime(e.target.value)}
            >
              <option>Less than 30 minutes</option>
              <option>30-60 minutes</option>
              <option>More than 1 hour</option>
            </select>
          </div>

          <div className="mb-6">
            <label className="block font-semibold mb-1">Complexity</label>
            <select
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              value={complexity}
              onChange={(e) => setComplexity(e.target.value)}
            >
              <option>Beginner</option>
              <option>Intermediate</option>
              <option>Advanced</option>
            </select>
          </div>

          <button
            onClick={handleSubmit}
            className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded w-full"
          >
            Generate Recipe
          </button>
        </div>

        {/* RIGHT - Recipe Output */}
        <div className="bg-white dark:bg-gray-700 rounded-xl shadow-md p-6">
          <h2 className="text-xl font-bold mb-4 text-center text-gray-800 dark:text-white">
            Recipe Details
          </h2>

          {error && (
            <p className="text-red-500 dark:text-red-400 text-center mb-4">
              {error}
            </p>
          )}
          {recipes.length === 0 ? (
            <p className="text-gray-500 dark:text-gray-300 text-center">
              No recipe yet. Fill out the form and click "Generate Recipe".
            </p>
          ) : (
            <div className="space-y-6">
              {recipes.map((recipe, index) => (
                <div
                  key={index}
                  className="rounded-xl bg-white dark:bg-gray-800 shadow-md p-4 border dark:border-gray-700 transition-all duration-300 max-h-96 overflow-y-auto scrollbar-thin scrollbar-thumb-gray-400 scrollbar-track-gray-200 dark:scrollbar-thumb-gray-600 dark:scrollbar-track-gray-700"
                >
                  {typeof recipe === "string" ? (
                    <div className="text-sm space-y-2 text-gray-800 dark:text-white">
                      {(() => {
                        const sections = {
                          title: "",
                          ingredients: [],
                          equipment: [],
                          instructions: [],
                          tips: [],
                        };
                        let currentSection = null;

                        // Split lines and parse
                        recipe.split("\n").forEach((line) => {
                          const trimmed = line.trim().replace(/\r$/, "");

                          // Detect headers with **...**
                          if (/^\*\*(.*?)\*\*$/.test(trimmed)) {
                            const headerText = trimmed
                              .replace(/\*\*/g, "")
                              .trim();
                            console.log("Detected Header:", headerText); // Debug log
                            if (
                              headerText.toLowerCase().includes("recipe title")
                            ) {
                              currentSection = "title";
                            } else if (
                              headerText.toLowerCase().includes("ingredients")
                            ) {
                              currentSection = "ingredients";
                            } else if (
                              headerText.toLowerCase().includes("equipment")
                            ) {
                              currentSection = "equipment";
                            } else if (
                              headerText.toLowerCase().includes("instructions")
                            ) {
                              currentSection = "instructions";
                            } else if (
                              headerText
                                .toLowerCase()
                                .includes("optional tips") ||
                              headerText
                                .toLowerCase()
                                .includes("serving or variations")
                            ) {
                              currentSection = "tips";
                            }
                          } else if (trimmed && currentSection) {
                            // Collect content
                            if (
                              (currentSection === "ingredients" ||
                                currentSection === "equipment" ||
                                currentSection === "tips") &&
                              /^[-•]/.test(trimmed)
                            ) {
                              sections[currentSection].push(
                                trimmed.replace(/^[-•]\s*/, "")
                              );
                            } else if (currentSection === "instructions") {
                              sections.instructions.push(trimmed);
                            } else if (currentSection === "title") {
                              sections.title = trimmed;
                            }
                          }
                        });

                        console.log("Parsed Sections:", sections); // Debug log

                        // Render sections
                        return (
                          <>
                            {sections.title && (
                              <h3 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-4">
                                {sections.title}
                              </h3>
                            )}
                            {sections.ingredients.length > 0 && (
                              <div>
                                <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2">
                                  Ingredients
                                </h4>
                                <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                                  {sections.ingredients.map((ing, i) => (
                                    <li key={i}>{ing}</li>
                                  ))}
                                </ul>
                              </div>
                            )}
                            {sections.equipment.length > 0 && (
                              <div>
                                <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">
                                  Equipment
                                </h4>
                                <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                                  {sections.equipment.map((eq, i) => (
                                    <li key={i}>{eq}</li>
                                  ))}
                                </ul>
                              </div>
                            )}
                            {sections.instructions.length > 0 && (
                              <div>
                                <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">
                                  Instructions
                                </h4>
                                <div className="text-sm text-gray-800 dark:text-gray-200 whitespace-pre-wrap leading-relaxed">
                                  {sections.instructions.map((step, i) => (
                                    <p key={i}>{step}</p>
                                  ))}
                                </div>
                              </div>
                            )}
                            {sections.tips.length > 0 && (
                              <div>
                                <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">
                                  Optional Tips & Variations
                                </h4>
                                <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                                  {sections.tips.map((tip, i) => (
                                    <li key={i}>{tip}</li>
                                  ))}
                                </ul>
                              </div>
                            )}
                          </>
                        );
                      })()}
                    </div>
                  ) : (
                    <>
                      {recipe.title && (
                        <h3 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-4">
                          {recipe.title}
                        </h3>
                      )}
                      {recipe.ingredients && (
                        <div>
                          <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2">
                            Ingredients
                          </h4>
                          <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                            {recipe.ingredients.map((ing, i) => (
                              <li key={i}>{ing}</li>
                            ))}
                          </ul>
                        </div>
                      )}
                      {recipe.equipment && (
                        <div>
                          <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">
                            Equipment
                          </h4>
                          <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                            {recipe.equipment.map((eq, i) => (
                              <li key={i}>{eq}</li>
                            ))}
                          </ul>
                        </div>
                      )}
                      {recipe.instructions && (
                        <div>
                          <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">
                            Instructions
                          </h4>
                          <div className="text-sm text-gray-800 dark:text-gray-200 whitespace-pre-wrap leading-relaxed">
                            {recipe.instructions}
                          </div>
                        </div>
                      )}
                      {recipe.tips && (
                        <div>
                          <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2 mt-4">
                            Optional Tips & Variations
                          </h4>
                          <div className="text-sm text-gray-800 dark:text-gray-200 whitespace-pre-wrap leading-relaxed">
                            {recipe.tips}
                          </div>
                        </div>
                      )}
                    </>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default App;
